/**
 * Resoniq-generated starting points for the M-VAVE TANK-G, limited to what the
 * hardware has (lib/devices/tank-g.ts): one gate, nine amp slots with a
 * five-knob stack, one modulation, one delay, one reverb, one IR.
 * Values are normalized 0–10 knob positions, never native readouts. None of
 * these were recorded or played on the hardware; every one is published with
 * the generated-content disclosure. Artist names describe a style a preset is
 * inspired by, never an endorsement or a claim about anyone's settings.
 */

type Mod = ["Chorus" | "Phaser" | "Tremolo", number, number];
type Dly = ["Analog" | "Tape" | "Dual", number, number];
type Rvb = ["Room" | "Spring" | "Cloud", number, number];
type Row = {
  k: string; n: string; c: TankGCollection; g: string[]; s: string[];
  /** [slot, Gain, Treble, Middle, Bass, Volume] */
  a: [number, number, number, number, number, number];
  gate?: number; mod?: Mod; dly?: Dly; rvb?: Rvb;
  cab: string; gtr: string; pu: "sc" | "hb" | "p90" | "active" | "hss"; pos: string; tun?: string;
  d: string; play: string; art?: string[];
};

