const LEVEL: Record<string, string> = {
  clean: "Level: clean slots need more VOLUME than distortion slots to feel equally loud. Compare against your loudest preset at the same MASTER and adjust VOLUME only (MASTER is global).",
  overdrive: "Level: match VOLUME against a clean preset at the same MASTER; overdrive slots read louder than they measure, so err slightly low.",
  distortion: "Level: high-gain slots are compressed, so a little VOLUME goes a long way. Set rhythm presets about one step below leads in the same bank.",
};

function pickupTips(gain: "clean" | "overdrive" | "distortion", lowTuned: boolean) {
  const tips = {
    clean: ["Single coils: as written; if it gets glassy, drop TREBLE about 0.5.", "Humbuckers: TREBLE up about 0.5–1 and BASS down 0.5; lower GAIN if chords start to break up."],
    overdrive: ["Single coils: GAIN up about 0.5–1, TREBLE down about 0.5 and NOISE GATE up about 0.5 for hum.", "Humbuckers: GAIN down about 1 and BASS down 0.5 so chords stay defined."],
    distortion: ["Single coils: GAIN up about 1, NOISE GATE up about 1 for hum, TREBLE down about 0.5.", "Humbuckers: passive as written; with active pickups lower GAIN about 1."],
  }[gain];
  return lowTuned ? [...tips, "Below drop C: BASS down about 1 more and NOISE GATE up about 0.5 to keep low notes tight."] : tips;
}

function build(r: Row): TonePreset {
  const [slot, gain, treble, middle, bass, volume] = r.a;
  const amp = tankGAmp(slot)!;
  const ref = { slug: TANK_G_SLUG };
  const chain: PresetBlock[] = [];
  const steps = [
    "1. Tap B+C to enter LIVE mode. Start with MASTER low.",
    `2. TYPE to slot ${slot} (${amp.voicing}; M-VAVE lists it as ${amp.reference}). GAIN ${gain} (${clock(gain)}), TREBLE ${treble}, MIDDLE ${middle}, BASS ${bass}, VOLUME ${volume}.`,
    r.gate ? `3. NOISE GATE ${r.gate} (${clock(r.gate)}).` : "3. NOISE GATE fully counter-clockwise (off).",
  ];
  if (r.gate) chain.push({ category: "gate", gear: ref, params: { Threshold: r.gate } });
  if (r.mod) {
    const [type, amount, speed] = r.mod;
    const key = TANK_G_MODULES.mod.types[type];
    chain.push({ category: type.toLowerCase() as "chorus" | "phaser" | "tremolo", gear: ref, placement: "loop", params: { Type: type, [key]: amount, Speed: speed } });
    steps.push(`4. MOD FX in the ${type} zone at ${amount}/10 of the zone (${key}); MOD SPEED ${speed}.`);
  } else steps.push("4. MOD FX between two zones (MOD lights off).");
  if (r.dly) {
    const [type, mix, time] = r.dly;
    chain.push({ category: "delay", gear: ref, placement: "loop", params: { Type: type, Mix: mix, Time: time } });
    steps.push(`5. DLY MIX in the ${type} zone at ${mix}/10 of the zone; DLY TIME ${time}${type === "Dual" || r.s.includes("dotted eighth") ? ", then fine-tune Time by ear to the song tempo" : ""}.`);
  } else steps.push("5. DLY MIX between two zones (DELAY lights off).");
  if (r.rvb) {
    const [type, decay, mix] = r.rvb;
    chain.push({ category: "reverb", gear: ref, placement: "loop", params: { Type: type, Decay: decay, Mix: mix } });
    steps.push(`6. RVB DECAY in the ${type} zone at ${decay}/10 of the zone; RVB MIX ${mix}.`);
  } else steps.push("6. RVB DECAY between two zones (REVERB lights off).");
  steps.push(`7. IR CAB: the slot holding a ${r.cab} IR (check names in M-EFCS, or import one).`, "8. Pick a bank with BANK−/BANK+, then hold A, B, C or D until it blinks quickly to save.");
  const lowTuned = !!r.tun && /drop [cba]|seven|open/i.test(r.tun) && amp.gain === "distortion";
  const setup = [...steps, "", LEVEL[amp.gain], "", ...pickupTips(amp.gain, lowTuned)].join("\n");
  const neighbour = tankGAmp(amp.gain === "clean" ? (slot === 1 ? 2 : 1) : slot === 9 ? 8 : slot + 1)!;
  return {
    key: `tank-g-${r.k}`,
    name: `${r.n} · TANK-G`,
    instrument: "GUITAR",
    genres: r.g,
    styles: r.s,
    description: r.d,
    player: { gear: { slug: r.gtr }, pickups: [PICKUPS[r.pu]], pickupPosition: r.pos, ...(r.tun && { tuning: r.tun }) },
    amp: { gear: ref, channel: `Slot ${slot} · ${amp.voicing}`, settings: { Gain: gain, Treble: treble, Middle: middle, Bass: bass, Volume: volume } },
    cab: { speakers: `${r.cab} IR` },
    chain,
    playing: r.play,
    setup,
    alternatives: [
      `Slot ${neighbour.slot} (${neighbour.voicing}) with the same tone stack`,
      "On another modeler: same amp family, tone stack and effect mix (e.g. Valeton GP-200, Boss GX-100)",
    ],
    ...(r.art && { artists: r.art }),
    device: { slug: TANK_G_SLUG, ampSlot: slot, collection: r.c },
  };
}

export const TANK_G_PRESETS: TonePreset[] = ROWS.map(build);
